def kth_smallest(nums, k):
    """
    Find the k-th smallest element in an unsorted list (1-indexed).

    Args:
        nums (list): The list of numbers.
        k (int): The 1-indexed position of the k-th smallest element.

    Returns:
        int: The k-th smallest element.
    """
    if not nums:
        raise ValueError("List cannot be empty")

    # Sort the list in ascending order
    sorted_nums = sorted(nums)

    # Return the element at index k-1 (1-indexed)
    return sorted_nums[k - 1]
