def is_balanced(s: str) -> bool:
    """Check if a string of brackets '()[]{}' is balanced."""
    stack = []
    for char in s:
        if char in '()[]{}':
            stack.append(char)
        elif char == '(':
            if not stack:
                return False
            stack.pop()
        elif char == ')':
            if not stack:
                return False
            stack.pop()
        elif char == '[':
            if not stack:
                return False
            stack.pop()
        elif char == ']':
            if not stack:
                return False
            stack.pop()
        elif char == '}':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0
